import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
SEED = HERE.parent / 'benchmark-v1'
qseed = json.loads((SEED / 'questions.json').read_text())
aseed = json.loads((SEED / 'answer-key.json').read_text())
rows = []

def add(section, question, facts, refs):
    rows.append({'id': f'Q{21+len(rows):02}', 'question': question,
                 'material_requested_facts': facts.split(' ~ '),
                 'expected_answer': facts.replace(' ~ ', ' '),
                 'source_references': refs, 'coverage_section': section})

# Pass 1: main rules, golden rules, and animal abilities.
add('main.setup', 'How are the conservation-track Bonus tiles selected and placed, and are components limited by the supplied quantity?',
    'Shuffle the 9 Bonus tiles and place 1 random face-up tile on each of the 4 blank yellow spaces, leaving the two printed-icon spaces uncovered. ~ Return the other 5 tiles to the box. ~ If a component runs out, use a suitable substitute.', 'Main p4 global setup 2/4')
add('main.setup', 'How are advanced zoo maps selected, and what fixed enclosure and kiosk begin on Map A?',
    'Each player may take 2 random maps and choose an advanced side, or lay out player count plus 1 advanced maps and choose in reverse turn order; return unused maps. ~ Map A starts with an empty size-3 standard enclosure on its indicated spaces and its printed kiosk is already built. ~ You may build adjacent to that kiosk.', 'Main pp4,6; FAQ p2 Map A; Main p6 map illustration')
add('main.setup', 'Where do the seven conservation-support tokens start, in what order are inactive association workers hired, and what map reward may hiring the last worker trigger?',
    'Seven player tokens cover the seven bonus spaces at the left edge of the zoo map; the other player tokens are personal supply. ~ Hire inactive workers from the lowest occupied storage space upward, moving them to the notepad as active. ~ Some maps grant conservation points for hiring the last worker.', 'Main pp5–7')
add('main.upgrades', 'When you earn an Action card upgrade, what happens to its position, when is the new action usable, when does it count for conditions, and can all five cards be upgraded?',
    'Flip one chosen side-I card to side II in its current slot. ~ Use the improved action from the next action onward, even if the upgrade occurred during that action; it immediately satisfies upgraded-card conditions. ~ Four upgrade opportunities are the conservation track, reputation track, second partner zoo and second university, with an alternative at one opportunity, so all five cannot be upgraded.', 'Main p8 upgrade paragraphs; FAQ p2 Other')
add('main.cards_table', 'For Cards I, give deck draw and discard counts at strengths 1 through 5, and explain which cards may satisfy a required discard.',
    'At strengths 1/2/3/4/5 draw 1/1/2/2/3 cards respectively, then discard 1/0/1/0/1 respectively. ~ A required discard may be a newly drawn card or an older hand card.', 'Main p2 Action-card table / p8 miniature table and p9 Drawing from the deck')
add('main.cards_table', 'For Cards II, give the draw and discard counts at strengths 1 through 5.',
    'At strengths 1/2/3/4/5 draw 1/2/2/3/4 cards respectively, then discard 0/1/0/1/1 respectively.', 'Main p2 Action-card table / p8 miniature table; Main p9')
add('main.animals_table', 'How many animals may Animals I and Animals II play at strengths 1 through 5, and when does Animals II give an additional reward?',
    'Animals I permits 0/1/1/1/2 animals at strengths 1/2/3/4/5 respectively. ~ A zero-animal regular action cannot be chosen because doing nothing is prohibited. ~ Animals II permits up to 1/1/2/2/2 animals at strengths 1/2/3/4/5 respectively. ~ At strength 5 or higher, Animals II may gain 1 reputation at the very beginning of the action.', 'Main p2 Action-card tables (Animals II visible strengths 4–5), Main pp8,11,13; accepted numeric-only original component supplement: original publisher Spielzene.jpg and 2021 Back_arche_nova.jpg matching original German component artwork, recorded in table-source-check/followup-source-report.json; coordinator-supplied ark-nova-original-physical-animals-II.png is a third-party 2022 review photograph of an original German card and is corroborating research history only; original English base scope retained')
add('main.animal_categories', 'Which animal categories count when an effect asks for animal categories, including bears and Petting Zoo animals?',
    'The seven categories are bird, herbivore, predator, primate, reptile, bear and Petting Zoo animal. ~ Bear and Petting Zoo animal count unless explicitly excluded. ~ A bear icon may occur with herbivore or predator icons and does not replace them; Petting Zoo is its own game category.', 'Main p13 Animal categories')
add('main.donations', 'What are all the conditions, printed cost ladder, cost selection, token source and reward for a donation, including the repeatable final space?',
    'Only an upgraded Association action allows a donation, and at least 1 association task must have been performed during that same action. ~ At most 1 donation is allowed per Association action and no additional worker is required. ~ The printed cost ladder is 2, 5, 5, 7, 7, 10, 10, then repeatable 12 money, with setup-blocked spaces unavailable. ~ Pay the lowest still-visible donation amount and cover it with a token from personal supply, gaining 1 conservation point. ~ Once only the last donation space remains, each donation costs 12 money without placing further tokens.', 'Main p16 Association II donation paragraphs; Main p14 Association-board donation diagram')
add('golden.icons', 'Which displayed symbols count as icons in your zoo, which do not, do effects count their own card and repeated icons, and which text wins if a card conflicts with a general rule?',
    'Count upper-right icons on your Animal and Sponsor cards and icons on your partner zoos and universities. ~ Water and rock requirements at the upper-left of Animal and unique-building cards count too. ~ Left-side play conditions and conservation-project icons do not count. ~ The card itself counts for both immediate and recurring effects; duplicate icons count and trigger effects twice. ~ Card text overrides conflicting general rules.', 'Glossary p1 Golden Rules; Main pp11,17; FAQ p3 continent icons')
add('golden.terrain', 'What satisfies a requirement for two water or rock spaces; do connected terrain regions or decorative illustrations count?',
    'The building must actually share edges with two distinct terrain hexes; one building hex may touch both. ~ Multiple building hexes touching the same terrain hex still count only once. ~ Adjacency to one hex of a connected two-hex water area is adjacency to only one water hex. ~ Water/rock illustrations on buildings and standard enclosures do not count as terrain requirements or terrain spaces.', 'Glossary p1 Double Icons; FAQ p2 Zoo maps/Other')
add('projects.release_reputation', 'Who gains the extra reputation on Release into the Wild projects, and how do Breeding Program projects differ in choosing a support space?',
    'Playing a Release into the Wild project from hand (or permitted display play) grants 1 reputation; supporting a project already in play does not grant that play bonus. ~ Breeding Program cards 123–127 have the same condition for all three spaces, so choose any free space and receive its depicted reward.', 'Glossary p1 Conservation Project Clarifications')
add('glossary.effect_syntax', 'How do you read an effect of the form X:Y when X has no number, says per, or lists numerical thresholds?',
    'The left side is the condition and the right side its reward. ~ With no number, or with per, receive the reward once for each fulfillment. ~ With one or more numbers on the left, receive only one reward; with several thresholds, use the highest fulfilled threshold.', 'Glossary p4 Effect Syntax')
add('glossary.terms', 'Define connected, isolated, border space, your zoo and any zoo.',
    'A connected space is not itself covered and is adjacent to at least 1 covered space. ~ An isolated space is not adjacent to a covered space. ~ A border space lacks another map space along at least 1 of its 6 sides. ~ Your zoo comprises your card display, map contents and personal supply. ~ Any zoo combines these for all players.', 'Glossary p4 Term Definitions; FAQ p3 border space')
add('glossary.unique_buildings', 'What are the payment, placement, orientation and enclosure/terrain rules for unique buildings, and may you play their Sponsor card if the tile cannot fit?',
    'You must place the matching unique-building tile when playing its card; if legal placement is impossible, you cannot play that card. ~ No building money cost is paid. ~ Apply usual building rules, keep the colored matching-icon side up, rotate freely but do not flip. ~ Unique buildings are not enclosures, cannot house additional animals, and never count as water or rock spaces.', 'Glossary p4 Unique buildings (cards 243–257)')
add('abilities.action_determination', 'For an animal granting a named Action versus Determination (Any Action), when do you perform it, how do cards move, and may you choose the X-token action?',
    'First finish the Animals action including moving Animals to slot 1. ~ Perform the granted action using the relevant own Action card normally and then move it to slot 1. ~ A named Action cannot be replaced by taking an X-token. ~ Determination permits any action, including the X-token action.', 'Glossary p2 Action/Determination; FAQ p3 final question')
add('abilities.assertion_dominance', 'Where do Assertion and Dominance get project cards, what if the named Dominance card is already in play, and where is an acquired base card later played?',
    'Search the face-down remaining base-project pile: Assertion chooses a card, Dominance takes its named card; add it to hand and return the pile. ~ Dominance does nothing if the named card is already in play. ~ Later play and support the acquired card using Association, above the board with normal played projects, not below with the setup base projects.', 'Glossary p2 Assertion/Dominance')
add('abilities.boost_clever', 'When do Boost and Clever resolve, which slots may they choose, and how do other cards shift when a card moves to 1 or 5?',
    'Resolve after finishing Animals and moving its card to slot 1. ~ Boost moves the named Action card to slot 1 or 5; Clever puts the chosen card into slot 1. ~ Moving to 1 shifts cards previously to its left one slot right; moving to 5 shifts cards previously to its right one slot left.', 'Glossary p2 Boost/Clever; FAQ p1 Boost')
add('abilities.interactive_eligibility', 'What appeal threshold makes a player eligible for Constriction, Hypnosis, Pilfering or Venom, how may the acting animal appeal affect target selection, and what multiplayer alternative exists?',
    'Only zoos with at least 5 appeal can be affected. ~ The acting player may resolve that animal appeal before or after the interactive ability, so normally its appeal need not count during target selection. ~ The group may use the printed alternate solo effects instead of interactive effects without removing the cards.', 'Main p11; Glossary pp2–3 interactive ability reminders; FAQ p1')
add('abilities.constriction', 'Where are Constriction 1/2 tokens placed, can they stack, how do they change strength and multiplied actions, and when are they removed?',
    'Constriction 1 targets the card in slot 5; Constriction 2 targets slots 4 and 5. ~ A card can have at most 1 Constriction token; return duplicate tokens. ~ Its action has strength reduced by 2, applying to both actions if multiplied, and X-tokens may raise strength. ~ Return the used token after the action, or unused tokens during the next break.', 'Glossary p2 Constriction')
add('abilities.constriction_low_strength', 'If a constricted card reaches slot 1 or 2, can it be used, and can it instead take an X-token?',
    'Its regular action has strength −1 or 0 and cannot be performed as is. ~ Spend enough X-tokens to reach at least strength 1, wait until it reaches slot 3, or use the alternative X-token action if below the holding cap.', 'Glossary p2 Constriction; Main p18')
add('abilities.digging', 'When Digging offers repeated choices, can you change your choice and when does discarding a display card refill the display?',
    'Choose separately after each card which option to use next. ~ If you discard a display card, immediately shift higher-folder cards down as needed and replenish, placing the new card in folder 6.', 'Glossary p2 Digging')
add('abilities.flock', 'When may a flock animal avoid occupying a new enclosure, how often can its host herbivore be reused, may a later non-flock animal share its own enclosure, and must you prove its original accommodation when releasing it?',
    'If another herbivore in your zoo requires an equal or larger standard enclosure, play the flock animal without flipping an enclosure. ~ The host may itself be flock or non-flock and can host any number of flock animals. ~ Without a suitable existing herbivore, occupy an enclosure normally; a later non-flock herbivore cannot move into that same enclosure. ~ Releasing a flock animal still permits freeing an occupied enclosure without proving it originally occupied one.', 'Glossary p2 Flock Animal; release procedure as in Q17')
add('abilities.full_throated', 'How does Full-throated hire an association worker, what map reward may apply, and what happens if all workers are hired?',
    'Move 1 worker from the lowest occupied storage space to the notepad, making it available immediately. ~ Apply any map bonus for hiring the last worker. ~ If all workers are already hired, it has no effect.', 'Glossary p2 Full-throated')
add('abilities.hunter', 'What does Hunter do if none of the revealed cards is an Animal card?',
    'Discard all revealed cards and take none.', 'Glossary p2 Hunter')
add('abilities.hypnosis', 'For Hypnosis, how are tied or self targets handled, whose card side and X-tokens apply, where does the used card go, and what happens to tokens on it?',
    'Among tied highest-appeal eligible zoos choose the affected player; if that is yourself, the ability has no effect. ~ Use your own X-tokens to raise strength. ~ Use the target Action card side for the entire copied action, while all other Action-card sides are your own. ~ Move the used target Action card to slot 1 normally. ~ Constriction and Venom on it affect you and are discarded afterwards; its Multiplier cannot be used.', 'Glossary pp2–3 Hypnosis; FAQ p1')
add('abilities.hypnosis_upgrade_scope', 'Under Hypnosis, can a copied upgraded Build or Animals card bypass your own corresponding upgrade, can copied Association I gain a third partner when yours is upgraded, and whose Build side governs a unique building played via copied Sponsors?',
    'Copied upgraded Build allows its special enclosures and upgrade-marked map spaces even if your Build is I; copied upgraded Animals allows upgrade-conditioned animals even if yours is I. ~ Copied Association I cannot take a third partner zoo even if your own Association is II. ~ When copied Sponsors plays a unique building, your own Build side determines permission for upgrade-marked map spaces.', 'Glossary pp2–3 Hypnosis examples 1–4')
add('abilities.jumping', 'Does Jumping to the last break space give the triggering X-token and interrupt the current turn?',
    'It gives 1 X-token subject to the usual holding limit and triggers the break. ~ Finish the entire current turn before the break.', 'Glossary p3 Jumping; Main pp7–8')
add('abilities.multiplier', 'Where is an earned Multiplier placed, how are two actions resolved, how do X-tokens and after-finishing effects work, may a break stop the second action, and when is the token returned?',
    'Immediately place the token on its named Action card; a bonus-tile Multiplier may go on any Action card, including Animals. ~ Next use may execute that action twice in succession at the same base strength, then move the card to slot 1. ~ Each spent X-token strengthens only one of the two actions. ~ Resolve after-finishing effects only after both actions. ~ You may choose different normal options of that action each time; a break triggered by the first waits until the complete turn ends. ~ Return the token after use or unused at the next break.', 'Glossary p3 Multiplier; FAQ pp1,3')
add('abilities.multiplier_stacking_x', 'What do two Multiplier tokens on one card provide, and may a multiplied card take X-tokens or mix an X-token action with a regular action?',
    'Multiple Multiplier tokens may share a card; each adds 1 extra action, so 2 tokens permit up to 3 actions. ~ A Multiplier may be used for 2 X-token actions, subject to the holding limit. ~ It cannot combine 1 X-token action and 1 regular action.', 'FAQ p3 Multiplier questions')
add('abilities.peacocking_posturing', 'Which Build upgrade exception applies to Peacocking, and what placement restrictions and sequential timing still apply to Peacocking and Posturing?',
    'Peacocking can place the Large Bird Aviary before Build is upgraded, but only if a legal site exists and the zoo does not already have one. ~ Other normal building rules still apply, including upgrade-marked map spaces. ~ Posturing follows normal placement rules, including kiosk distance; multiple buildings are placed one after another.', 'Glossary p3 Peacocking/Posturing; FAQ p1 map upgrade restriction')
add('abilities.petting', 'How much appeal does each successive Petting Zoo animal gain, how many may a zoo hold, and do these count as small animals?',
    'The first gains 3 appeal, the second 6 and the third 9. ~ At most 3 Petting Zoo animals can be held because only 1 Petting Zoo is allowed. ~ They count as small animals.', 'Glossary p3 Petting Zoo animal')
add('abilities.pilfering_target', 'How does Pilfering resolve ties, zero conservation, or selecting yourself as affected player?',
    'Choose among tied eligible zoos with highest appeal or most conservation as specified. ~ Most-conservation targeting requires at least 1 conservation point. ~ If the affected player is yourself, the ability has no effect.', 'Glossary p3 Pilfering; FAQ p1 Japanese Macaque')
add('abilities.pilfering_payment', 'Who chooses the Pilfering payment, which cards may be drawn, what if cards or money are missing, and how does repeated Pilfering resolve?',
    'The affected player chooses a random hand-card draw (excluding Final Scoring cards) or paying 5 money. ~ With no hand cards they must pay 5; with less than 5 money they must allow a hand-card draw. ~ With neither hand cards nor 5 money, give all remaining money, possibly zero. ~ Repeated pilferings resolve sequentially, with a fresh choice after each result.', 'Glossary p3 Pilfering')
add('abilities.pouch_sunbathing', 'What happens to cards put under an animal by Pouch, including after release, and to cards sold by Sunbathing?',
    'Pouched cards no longer function. ~ If that animal is released, discard its tucked cards but retain appeal already gained. ~ Sold Sunbathing cards go to the discard pile.', 'Glossary p3 Pouch/Sunbathing')
add('abilities.resistance', 'How does Resistance interact with the 10-conservation Final Scoring discard and scoring multiple Final Scoring cards?',
    'Resistance can give an extra Final Scoring card. ~ If obtained before anyone reaches 10 conservation, choose any one of all your Final Scoring cards to discard when that threshold is first reached. ~ Score all Final Scoring cards you still hold at the end, each subject to its own 4-conservation cap.', 'Glossary p3 Resistance; Main p19')
add('abilities.scavenging', 'How are cards selected from the discard pile by Scavenging?',
    'Shuffle the discard pile face down and draw randomly from it, then return the pile face up.', 'Glossary p3 Scavenging')
add('abilities.snapping_magnet', 'How do the Snapping and Sponsor Magnet animal abilities differ in permitted card source and reputation restriction, including empty results and refill timing?',
    'Snapping must take a display card, ignoring reputation, and cannot draw from the deck. ~ Sponsor Magnet ignores reputation for Sponsor cards in the display; if there are none it has no effect. ~ Replenish the display at the end of the turn.', 'Glossary p3 Snapping/Sponsor Magnet; Main p9')
add('abilities.venom', 'Where are Venom tokens placed, can they stack, what happens when a marked card is used, what happens at turn end if no token was removed, and when do unused tokens expire?',
    'Place tokens on the lowest-slot Action cards starting at slot 1; at most 1 Venom token per card and return duplicates. ~ Using a marked card removes its token and suppresses effects of Venom on your other cards that turn. ~ If no Venom token was removed that turn and any remains on a card at turn end, pay 2 money. ~ If unable to pay, undo the turn and choose a different action; spending all money does not avoid payment. ~ Remove remaining Venom tokens without effect at the next break.', 'Glossary p3 Venom')
add('abilities.venom_x', 'Can the alternative X-token action on a Venom-marked Action card clear Venom, and what prevents that choice?',
    'Yes, use the marked card for the X-token action and discard its Venom token. ~ You cannot choose the X-token action when already holding 5 X-tokens.', 'FAQ p2 Other')

PASS1_END = len(rows)

# Pass 2: every individual Sponsor clarification, with genuinely shared patterns grouped.
add('sponsor.201', 'What are Science Lab 201 card-taking timing, source options and reputation restriction, and its final research thresholds?',
    'On play and in every break income phase, you may take a display card in reputation range or draw a deck card. ~ At final scoring gain 1 conservation for 3–5 research icons or 2 for 6 or more.', 'Glossary p4 Science Lab 201')
add('sponsor.202', 'What triggers Spokesperson 202 and does the research icon on Spokesperson itself trigger it?',
    'Each research icon played into your zoo gains 1 reputation. ~ Its own research icon triggers it immediately when played.', 'Glossary p4 Spokesperson 202; p1 Cards Always Count Themselves')
add('sponsor.203', 'What are Veterinarian 203 immediate university rewards, revised conservation-task strength and final reward?',
    'Gain 2/5/10 money for 1/2/3 universities respectively when played. ~ Supporting a conservation project through Association requires strength 4 instead of 5. ~ Gain 1 conservation at final scoring if you have 3 universities.', 'Glossary p4 Veterinarian 203')
add('sponsor.204', 'What does Science Museum 204 award on play and for later research icons?',
    'On play gain 2 money per research icon in your zoo. ~ Each research icon played into your zoo gains 1 conservation point.', 'Glossary p4 Science Museum 204')
add('sponsor.205', 'What immediate rewards does Gorilla Field Research 205 give?',
    'Gain 2 reputation and 1 conservation point when played.', 'Glossary p4 Gorilla Field Research 205')
add('sponsor.206', 'How does Medical Breakthrough 206 count past support for its immediate reward, and what does it give at breaks?',
    'Gain 2 appeal for every conservation project already supported, counted by missing tokens from the left of your map. ~ Gain 1 conservation in each break income phase.', 'Glossary p4 Medical Breakthrough 206')
add('sponsor.207', 'How does Basic Research 207 count icons and reward its owner and the other players?',
    'Count different animal-category and continent icons, not repeated copies of an icon or research icons. ~ Gain 1 conservation per 2 different icons, rounding down. ~ Every other player gains 2 money per conservation point gained this way.', 'Glossary p5 Basic Research 207')
add('sponsor.208', 'What does Science Library 208 give on play, whose research-icon plays earn its recurring reward, and what is its final condition?',
    'On play gain 1 appeal per research icon in your zoo. ~ Whenever a research icon is played in any zoo, gain 2 money. ~ At final scoring gain 1 conservation if you have at least 5 different animal-category icons.', 'Glossary p5 Science Library 208')
add('sponsor.209', 'What does Technology Institute 209 give immediately and at breaks, and what final condition does it score?',
    'On play and in each break income phase gain 1 X-token, subject to the cap of 5. ~ At final scoring gain 1 conservation if you have 3 universities.', 'Glossary p5 Technology Institute 209')
add('sponsor.210', 'For Expert on the Americas 210, what is the immediate icon reward, what may each new Americas icon build and under which restrictions, and what is the final condition?',
    'On play gain 1 appeal per Americas icon in your zoo. ~ Each Americas icon played into your zoo lets you place 1 kiosk for free, following normal building rules including kiosk spacing. ~ Gain 1 conservation at final scoring for 5 or more kiosks.', 'Glossary p5 Expert on the Americas 210')
add('sponsor.211', 'For Expert on Europe 211, what are the immediate reward, recurring building and final enclosure condition?',
    'On play gain 1 appeal per Europe icon in your zoo. ~ Each Europe icon played into your zoo lets you place a 1-space enclosure for free under normal building rules. ~ Gain 1 conservation at final scoring for at least 5 occupied 1-space enclosures.', 'Glossary p5 Expert on Europe 211')
add('sponsor.212', 'What does Expert on Australia 212 do immediately and for each new Australia icon, and what becomes of tucked cards?',
    'On play gain 1 appeal per Australia icon in your zoo. ~ Each Australia icon played into your zoo lets you place 1 hand card beneath this Sponsor to gain 2 appeal. ~ The tucked card has no further function.', 'Glossary p5 Expert on Australia 212')
add('sponsor.213', 'What are Expert on Asia 213 immediate and recurring rewards, and do normal building rules apply?',
    'On play gain 1 appeal per Asia icon in your zoo. ~ Each Asia icon played into your zoo lets you place 1 pavilion for free, following normal building rules.', 'Glossary p5 Expert on Asia 213')
add('sponsor.214', 'What does Expert on Africa 214 grant immediately, when does its card-reposition effect occur, and how does it score at the end?',
    'On play gain 1 appeal per Africa icon in your zoo. ~ Each Africa icon played into your zoo lets you put any Action card in slot 1 after finishing the current action, after the used card has already moved to slot 1. ~ At final scoring gain 1 appeal per X-token in personal supply.', 'Glossary p5 Expert on Africa 214')
add('sponsor.215_218', 'How do Global Breeding Program 215 and Breeding Program 218 store and spend substitutes, which projects qualify, and what is the final condition?',
    'Place 2 tokens from personal supply on the card when played. ~ When supporting a base project below the Association board, return exactly 1 token as any needed icon; never use both on the same project. ~ A base card later played above the board does not qualify. ~ At final scoring gain 1 conservation for supporting projects 5 or more times, counted by missing map tokens. ~ Card 218 has different play conditions but otherwise works identically.', 'Glossary p5 Global Breeding Program 215 / Breeding Program 218')
add('sponsor.216', 'What worker benefit and final reward does Talented Communicator 216 give?',
    'Immediately hire 1 worker from the lowest occupied storage space, available at once, applying any final-worker map reward; if all are hired this part has no effect. ~ Gain 1 conservation at final scoring if reputation is at least 9.', 'Glossary p5 Talented Communicator 216')
add('sponsor.217', 'How does Engineer 217 change a Build action, including strength, payment, duplicate limits and special enclosures, and what is its final reward?',
    'Each Build action may build exactly 1 extra copy of one building built by that action without requiring extra strength. ~ Pay its normal money cost and obey normal placement rules. ~ With multiple original buildings, choose only 1 to duplicate; special enclosures cannot be duplicated. ~ Gain 5 appeal at final scoring if all map building spaces are covered, excluding rock and water.', 'Glossary p5 Engineer 217 and example')
add('sponsor.219', 'What does Diversity Researcher 219 give immediately, how does it change terrain building and requirements, what happens to covered terrain for other cards, and how does it score?',
    'On play gain 2 money per water and rock icon in your zoo, including icons on cards 241/242 and terrain requirements. ~ You may cover water and rock map spaces, but need not cover them for map completion. ~ Ignore water and rock requirements when playing animals and unique buildings, while their printed icons still count. ~ Covered terrain no longer counts for Hydrologist 241, Geologist 242 or Architectural Zoo 004. ~ At final scoring gain 2 appeal per set of 1 water icon and 1 rock icon, maximum 3 sets.', 'Glossary p5 Diversity Researcher 219')
add('sponsor.220', 'When does Federal Grants 220 give money, and what is its final condition?',
    'Gain 3 money on play and in each break income phase. ~ At final scoring gain 1 conservation if reputation is at least 9.', 'Glossary p5 Federal Grants 220')
add('sponsor.221', 'What triggers Archaeologist 221, what extra placement bonus may it choose, can simultaneous triggers choose the same bonus, and what is its final condition?',
    'Each placement bonus gained on a border space triggers an additional free placement bonus of your choice. ~ Choose any still-uncovered placement bonus anywhere on your map, including away from the border. ~ Multiple simultaneous border bonuses each grant an extra; those extras may choose the same or different eligible bonuses, and all bonuses resolve in your chosen order. ~ Gain 1 conservation at final scoring if all border building spaces are covered, excluding water and rock.', 'Glossary p5 Archaeologist 221')
add('sponsor.222', 'What are Release of Patents 222 owner reward, cap and other-player rewards?',
    'Gain 1 conservation per research icon in your zoo, maximum 3. ~ Each other player gains 2 money for every conservation point gained this way.', 'Glossary p5 Release of Patents 222')
add('sponsor.224', 'What immediate reward does Migration Recording 224 give, and how does it change release-project rewards and repeated support, including the per-action limit and counting supported projects?',
    'On play gain 1 X-token subject to the cap. ~ Each supported Release into the Wild project 113–122 gives 1 additional conservation. ~ You may support the same release project repeatedly by releasing another qualifying animal, but may put only 1 support token on a given project per Association action. ~ Each support token counts as a separately supported project for other effects.', 'Glossary p5 Migration Recording 224')
add('sponsor.225', 'What does Quarantine Lab 225 give immediately, which effects does it block or redirect, and what is its final condition?',
    'On play gain 1 X-token subject to the cap. ~ Venom, Constriction, Hypnosis and Pilfering do not affect you. ~ Hypnosis or Pilfering instead targets the next player meeting its criterion, if possible, ignoring your track counters. ~ Gain 1 conservation at final scoring for all 5 continent icons in your zoo.', 'Glossary p5 Quarantine Lab 225')
add('sponsor.226', 'What are Foreign Institute 226 immediate reward and final condition?',
    'Gain 2 reputation when played. ~ Gain 1 conservation at final scoring for all 5 continent icons in your zoo.', 'Glossary p6 Foreign Institute 226')
add('sponsor.227', 'How does WAZA Special Assignment 227 choose and find an animal, which animals become prohibited, and what rewards apply to small, large and size-3 animals?',
    'Choose small or large for the rest of the game and mark its box with a supply token. ~ Reveal deck cards until an Animal of that type appears, add it to hand, and discard the rest. ~ Every played chosen-type animal gives 2 appeal if small or 4 if large. ~ You may no longer play animals of the unchosen type. ~ Small means printed standard size 1–2 or Petting Zoo animal; large means standard size 4–5. ~ Size-3 animals remain legal but receive no bonus.', 'Glossary p6 WAZA Special Assignment 227')
add('sponsor.228', 'What does WAZA Small Animals Program 228 give on play, which Animals actions qualify for its extra animal, and how is the subsequent display card obtained?',
    'On play gain 2 money per small animal in your zoo. ~ If every animal played in the Animals action was small (size 1–2 or Petting Zoo), you may play 1 additional small animal from hand at normal cost and requirements. ~ Afterwards add 1 small animal from the display to hand if available, ignoring reputation. ~ This display take is allowed even if you decline the additional hand animal; a mixed small/large action does not qualify.', 'Glossary p6 WAZA Small Animals Program 228; FAQ p1')
add('sponsor.229_230', 'Compare Expert in Small Animals 229 and Expert in Large Animals 230 for immediate appeal, ongoing discounts and which animals qualify.',
    '229 gives 1 appeal per small animal on play and reduces the printed animal cost by 3 whenever playing a small animal. ~ Small animals have printed standard size 1–2 or are Petting Zoo animals. ~ 230 gives 2 appeal per large animal on play and a 4-money discount for each played large animal. ~ Large animals have printed standard size 4–5.', 'Glossary p6 Experts in Small/Large Animals 229–230')
add('sponsor.231_235', 'How do Sponsorship cards 231–235 give immediate appeal and tiered break income, and which category belongs to each named card?',
    'On play gain 1 appeal per matching category icon in your zoo. ~ Each break gain 3 money for 1–2 matching icons, 6 for 3–4 or 9 for 5 or more; use one tier. ~ 231 Primates uses primate icons; 232 Reptiles uses reptile; 233 Vultures uses bird; 234 Lions uses predator; 235 Elephants uses herbivore.', 'Glossary p6 Sponsorship 231–235')
