def write_outputs():
    questions = {**qseed, 'benchmark_version': 'coverage-draft-expanded',
                 'scope': 'Original English base main v1.2 + base glossary + official base FAQ + accepted official original base Icon Overview; original component images supplement hidden Animals II numeric cells and tiny reputation-board numerals only; exclude solo, Marine Worlds and strategy-guide authority',
                 'questions': qseed['questions'] + [{k:r[k] for k in ['id','question']} for r in rows]}
    answers = {**aseed, 'benchmark_version': 'coverage-draft-expanded',
               'answers': aseed['answers'] + [{k:r[k] for k in ['id','expected_answer','source_references','material_requested_facts']} for r in rows]}
    (HERE/'questions.json').write_text(json.dumps(questions, indent=2, ensure_ascii=False)+'\n')
    (HERE/'answer-key.json').write_text(json.dumps(answers, indent=2, ensure_ascii=False)+'\n')
    (HERE/'authored-rows.json').write_text(json.dumps(rows, indent=2, ensure_ascii=False)+'\n')
    assert questions['questions'][:20] == qseed['questions']
    assert answers['answers'][:20] == aseed['answers']
    assert len({r['id'] for r in questions['questions']}) == len(questions['questions'])
    print(f'{len(questions["questions"])} questions; {len(rows)} additions; original twenty exact')

if __name__ == '__main__':
    write_outputs()
